375	// nodeFileHexPath mirrors the per-node file naming used by the store.
376	func nodeFileHexPath(dir, node string) string {
377		return filepath.Join(dir, "nodes", hex.EncodeToString([]byte(node))+".json")
378	}
379	
380	// corruptNodeFile overwrites one node's saved file with raw content.
381	func corruptNodeFile(t *testing.T, dir, node, content string) {
382		t.Helper()
383		if err := os.WriteFile(nodeFileHexPath(dir, node), []byte(content), 0o644); err != nil {
384			t.Fatal(err)
385		}
386	}
387	
388	// readNodeFile returns the current raw bytes of a node's file.
389	func readNodeFile(t *testing.T, dir, node string) string {
390		t.Helper()
391		b, err := os.ReadFile(nodeFileHexPath(dir, node))
392		if err != nil {
393			t.Fatal(err)
394		}
395		return string(b)
396	}
