650		}
651		if strings.Contains(out, "submitted") {
652			t.Errorf("rejected batch must not print success counts, stdout=%q", out)
653		}
654		if !strings.Contains(errOut, "record 2") || !strings.Contains(errOut, "node") {
655			t.Errorf("stderr must name the failing record and the node field, got %q", errOut)
