// validateRawText checks the raw JSON string token of a text field before its
// decoded value is trusted. encoding/json silently rewrites invalid UTF-8 bytes
// and unpaired \u surrogate escapes to U+FFFD, which would merge distinct
// values into one replacement-char string — for node ids it breaks the
// ownership check against stored files, and for versions it would treat
// different reports as duplicates of a version the node never reported. The
// raw token must decode losslessly: every literal byte sequence must be
// valid UTF-8, and every \u escape must be a valid scalar value or a
// properly paired high/low surrogate pair. A literal "�" (or its �
// escape) is valid text the user typed and is accepted; only undecodable
// input is rejected. A backslash that genuinely belongs to the text is not
// re-interpreted here — only JSON escapes inside the raw token are walked.
func validateRawText(field string, raw json.RawMessage) error {
	raw = bytes.TrimSpace(raw)
	if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
		return fmt.Errorf("%s must be a string", field)
	}
	s := raw[1 : len(raw)-1]
	for i := 0; i < len(s); {
		c := s[i]
		if c == '\\' {
			if i+1 >= len(s) {
				return fmt.Errorf("%s contains a truncated escape", field)
			}
			if s[i+1] != 'u' {
				i += 2
				continue
			}
			if i+6 > len(s) {
				return fmt.Errorf("%s contains a truncated \\u escape", field)
			}
			r, err := parseHex4(s[i+2 : i+6])
			if err != nil {
				return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
			}
			switch {
			case r >= 0xD800 && r <= 0xDBFF:
				// A high surrogate is only valid when immediately followed
				// by a low-surrogate \u escape.
				if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
					return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
				}
				lo, err := parseHex4(s[i+8 : i+12])
				if err != nil {
					return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
				}
				if lo < 0xDC00 || lo > 0xDFFF {
					return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
				}
				i += 12
			case r >= 0xDC00 && r <= 0xDFFF:
				return fmt.Errorf("%s contains an unpaired low surrogate \\u%04X", field, r)
			default:
				i += 6
			}
			continue
		}
		if c < utf8.RuneSelf {
			i++
			continue
		}
		// A valid multi-byte rune decodes with size >= 2; size 1 means the
		// bytes are not valid UTF-8 (including surrogate encodings).
		_, size := utf8.DecodeRune(s[i:])
		if size == 1 {
			return fmt.Errorf("%s contains invalid UTF-8 at byte offset %d", field, i)
		}
		i += size
	}
	return nil
}

